      { withoutVisual: { type: 'flow', title: 'Quibi: $1.75B on Intuition', nodes: [{ label: 'No market testing or validation', sprite: 'question', explain: 'Katzenberg had 40 years in Hollywood and used that instead of a test. A few weeks of real users on a rough version would have returned the same answer that $1.75 billion eventually returned.' }, { label: '500K subs vs 7.4M target', sprite: 'chart-down', explain: '500,000 against 7.4 million is not a near miss, it is 7 percent of the plan. Every cost in the company, the shows, the servers, the ad buys, had already been sized for the other 93 percent.' }, { label: 'Dead in 6 months', sprite: 'crack', explain: 'Two years of building, $1.75 billion spent, six months alive. The test that would have said this costs weeks, and skipping it was supposed to be the fast option.' }], sentiment: 'negative', sprite: 'dice' }, withVisual: { type: 'flow', title: 'Netflix: Data-Driven Mastery', nodes: [{ label: 'A/B test every feature', sprite: 'magnifier', explain: 'The Top 10 row went to a small slice of users first and came back with 20 percent more engagement before anyone else saw it. Netflix runs 250 or more tests on thumbnails alone, so bad ideas die small and cheap.' }, { label: 'Algorithm = 80% of viewing', sprite: 'target', explain: 'Four out of every five things watched on Netflix were suggested, not searched for. The size of the catalogue matters far less than which row you land on when the screen loads.' }, { label: 'Saves $1B/year', sprite: 'stack-cash', explain: 'That billion is not new sales, it is subscribers who did not cancel. Money you keep counts the same as money you win, which is why the data infrastructure bill never gets argued about.' }], sentiment: 'positive', sprite: 'chart-up' } }
